import { canonicalSha256 } from '../core/canonical-json.mjs';
function splitLines(text){return String(text??'').replace(/\r\n/g,'\n').split('\n');}
function interesting(line){return /\b(fail(?:ed|ure)?|error|exception|panic|fatal|warning|assert|expected|actual|timeout|denied|invalid|not found)\b/i.test(line)||/\bat\s+.+:\d+:\d+/.test(line);}
function ranges(lines){const indexes=[];for(let i=0;i<lines.length;i++)if(interesting(lines[i]))indexes.push(i);const selected=new Set();for(const index of indexes)for(let i=Math.max(0,index-1);i<=Math.min(lines.length-1,index+2);i++)selected.add(i);const sorted=[...selected].sort((a,b)=>a-b);const output=[];let current=null;for(const index of sorted){if(!current||index>current.end+1){current={start:index+1,end:index+1,text:lines[index]};output.push(current);}else{current.end=index+1;current.text+=`\n${lines[index]}`;}}return output;}
export async function distillToolOutput({command,exitCode,durationMs,stdout='',stderr='',blobStore,tokenRegistry,model}){if(!blobStore||!tokenRegistry)throw new TypeError('blobStore and tokenRegistry are required');const rawText=[stdout,stderr].filter(Boolean).join('\n');const raw=await blobStore.put(rawText,{mimeType:'text/plain'});const lines=splitLines(rawText);const relevantRanges=ranges(lines);const status=Number(exitCode)===0?'passed':'failed';const summaryLines=[];summaryLines.push(`${status.toUpperCase()} ${command} (exit ${exitCode}, ${durationMs}ms)`);for(const range of relevantRanges.slice(0,8))summaryLines.push(range.text);if(relevantRanges.length===0)summaryLines.push(...lines.filter(Boolean).slice(-8));const summary=summaryLines.join('\n').slice(0,12000);const rawTokens=await tokenRegistry.countText(model,rawText);const distilledTokens=await tokenRegistry.countText(model,summary);const subject={schemaVersion:1,command:String(command),exitCode:Number(exitCode),durationMs:Number(durationMs),status,summary,relevantRanges,raw,accounting:{rawTokens,distilledTokens,reductionRatio:rawTokens?1-distilledTokens/rawTokens:0}};return Object.freeze({...subject,receiptSha256:canonicalSha256(subject)});}
